CG3_INLINE AABBTree3::AABBTree3(const Dcel& d, bool forDistanceQueries) :
    forDistanceQueries(forDistanceQueries)
{
    treeType = DCEL;
    for (Dcel::ConstVertexIterator vit = d.vertexBegin(); vit != d.vertexEnd(); ++vit){
        const Dcel::Vertex* v = *vit;
